package com.InnovaServe.core.service;import com.InnovaServe.core.entity.StaffRole;import com.InnovaServe.core.repository.StaffRoleRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service @Transactional(readOnly=true)public class StaffRoleService{private final StaffRoleRepository roles;private final TenantContext tenant;public StaffRoleService(StaffRoleRepository roles,TenantContext tenant){this.roles=roles;this.tenant=tenant;}public List<StaffRole> list(){return roles.findAllByTenantIdOrderByName(tenant.tenantId());}@Transactional public StaffRole create(String name,List<String> permissions){return roles.save(new StaffRole(tenant.tenantId(),name,permissions));}}
